<math xmlns="http://www.w3.org/1998/Math/MathML" dir="rtl" display="block"><mrow><mi mathvariant="normal">ت</mi><mo>=</mo><mfrac><mn dir="ltr">٤</mn><mn dir="ltr">٥</mn></mfrac><msup><mrow><mo stretchy="false">(</mo><mn dir="ltr">١</mn><mo>+</mo><msqrt><mi mathvariant="normal">س</mi></msqrt><mo stretchy="false">)</mo></mrow><mrow><mfrac><mn dir="ltr">٥</mn><mn dir="ltr">٢</mn></mfrac></mrow></msup><mo>−</mo><mfrac><mn dir="ltr">٤</mn><mn dir="ltr">٣</mn></mfrac><msup><mrow><mo stretchy="false">(</mo><mn dir="ltr">١</mn><mo>+</mo><msqrt><mi mathvariant="normal">س</mi></msqrt><mo stretchy="false">)</mo></mrow><mrow><mfrac><mn dir="ltr">٣</mn><mn dir="ltr">٢</mn></mfrac></mrow></msup><mo>+</mo><mi mathvariant="normal">جـ</mi></mrow></math>
